package dev.risingheroes.core;

import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class MissionRulesTest {
    private HeroProfile ready(){var p=new HeroProfile();HeroRules.assign(p,"explosion");p.schoolStage=4;return p;}
    private void complete(HeroProfile p,String id){MissionRules.start(p,id,100);while(!p.mission.completed){var s=MissionRules.stage(p);for(int i=0;i<s.count();i++)assertTrue(MissionRules.witness(p,p.mission.session,s.type(),s.role(),s.id()+"-"+i));}MissionRules.leave(p);}
    @Test void allAuthoredDefinitionsHaveReachablePathsAndValidObjectives(){assertEquals(28,MissionCatalog.all().size());for(var m:MissionCatalog.all())m.validate();assertEquals(10,MissionCatalog.all().stream().filter(m->m.path().equals("hero")).count());}
    @Test void schoolChainCannotBeSkippedAndLicenceRequiresCompletedExamination(){var p=ready();assertThrows(IllegalArgumentException.class,()->MissionRules.start(p,"school_provisional_exam",100));for(var m:MissionCatalog.all())if(m.path().equals("hero")){if(m.id().equals("school_provisional_exam"))assertEquals(0,p.licence);complete(p,m.id());if(m.id().equals("school_provisional_exam"))assertEquals(1,p.licence);}assertEquals(2,p.licence);assertEquals(10,p.completedMissions.size());}
    @Test void villainAndIndependentRewardsNeverGrantHeroCredentials(){for(String path:List.of("villain","independent")){var p=ready();for(var m:MissionCatalog.all())if(m.path().equals(path))complete(p,m.id());assertEquals(0,p.licence);assertTrue(p.credits>1000);assertTrue(p.reputation.get(path)>0);assertFalse(p.liveTokens.isEmpty());}}
    @Test void duplicateWrongRoleAndStaleSessionWitnessesCannotAdvance(){var p=ready();MissionRules.start(p,"school_assessment",100);var s=MissionRules.stage(p);assertFalse(MissionRules.witness(p,"stale",s.type(),s.role(),"one"));assertFalse(MissionRules.witness(p,p.mission.session,"COMBAT",s.role(),"one"));assertFalse(MissionRules.witness(p,p.mission.session,s.type(),"spoofed","one"));assertEquals(0,p.mission.step);assertTrue(MissionRules.witness(p,p.mission.session,s.type(),s.role(),"one"));var combat=MissionRules.stage(p);assertTrue(MissionRules.witness(p,p.mission.session,combat.type(),combat.role(),"robot-one"));assertFalse(MissionRules.witness(p,p.mission.session,combat.type(),combat.role(),"robot-one"));assertEquals(1,p.mission.step);}
    @Test void checkpointSurvivesReloadAndReturningDoesNotReaward(){var p=ready();complete(p,"school_assessment");int credits=p.credits;int tokens=p.liveTokens.size();p=HeroProfile.fromJson(Catalog.JSON.toJson(p));complete(p,"school_assessment");assertEquals(credits,p.credits);assertEquals(tokens,p.liveTokens.size());assertEquals(1,p.completedMissions.size());}
    @Test void activeAssignmentsLockQuirkLoadoutPresetsAndTechniqueTrials(){var p=ready();MissionRules.start(p,"school_assessment",100);assertThrows(IllegalArgumentException.class,()->HeroRules.assign(p,"explosion"));assertThrows(IllegalArgumentException.class,()->HeroRules.equip(p,0,"palm_burst",200));assertThrows(IllegalArgumentException.class,()->HeroRules.savePreset(p,"1",200));assertThrows(IllegalArgumentException.class,()->HeroRules.loadPreset(p,"1",200));assertThrows(IllegalArgumentException.class,()->TrialRules.start(p,"precision",200));}
    @Test void interruptedMissionResumesAtTheLastCompletedStage(){var p=ready();MissionRules.start(p,"school_assessment",100);var s=MissionRules.stage(p);MissionRules.witness(p,p.mission.session,s.type(),s.role(),"console");MissionRules.leave(p);p=HeroProfile.fromJson(Catalog.JSON.toJson(p));MissionRules.start(p,"school_assessment",200);assertEquals(1,p.mission.step);assertEquals(0,p.credits);}
    @Test void v2MigrationPreservesExistingRecordsAndIsIdempotent(){var p=ready();p.version=2;p.credits=750;p.masteries.put("explosion",50);p.loadoutPresets.put("explosion#1",new ArrayList<>(p.slots));p.liveTokens.add("earned");var restored=HeroProfile.fromJson(Catalog.JSON.toJson(p));assertEquals(4,restored.version);assertEquals(750,restored.credits);assertEquals(50,restored.mastery());assertEquals(p.loadoutPresets,restored.loadoutPresets);assertEquals(p.liveTokens,restored.liveTokens);restored.migrate();assertTrue(restored.completedMissions.isEmpty());assertEquals(750,restored.credits);}
}
